import 'package:dartz/dartz.dart'; import '../../../../core/errors/failure.dart'; import '../../../../core/result.dart'; import '../../domain/entities/monthly_closing.dart'; import '../../domain/repositories/monthly_closing_repository.dart'; import '../datasources/monthly_closing_remote_data_source.dart'; import '../models/monthly_closing_model.dart'; class MonthlyClosingRepositoryImpl implements MonthlyClosingRepository { MonthlyClosingRepositoryImpl(this.remote); final MonthlyClosingRemoteDataSource remote; @override Future<Result<List<MonthlyClosing>>> list() async {try{return Right((await remote.list()).map(MonthlyClosingModel.fromMap).toList(growable:false));}catch(e){return Left(ServerFailure('تعذر تحميل أرشيف الإقفال الشهري.',cause:e));}} @override Future<Result<String>> close(DateTime month,{String note=''}) async {try{return Right(await remote.close(DateTime(month.year,month.month,1),note));}catch(e){return Left(ServerFailure('تعذر إقفال الشهر. تحقق من عدم إقفاله مسبقًا وأن الفترة المحاسبية صحيحة.',cause:e));}} @override Future<Result<String>> reopen(DateTime month,String reason) async {if(reason.trim().isEmpty)return const Left(ValidationFailure('سبب إعادة فتح الشهر مطلوب.'));try{return Right(await remote.reopen(DateTime(month.year,month.month,1),reason));}catch(e){return Left(ServerFailure('تعذر إعادة فتح الشهر.',cause:e));}} }
